/// The `FridaWaitKind` enumeration.
///
/// Raw values this version has no variant for convert to [`Self::Unknown`]. It
/// displays as, and parses from, frida-core's name for it (its nick).
#[cfg(not(windows))]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum WaitKind {
    /// `FRIDA_WAIT_KIND_EXITED`.
    Exited,
    /// `FRIDA_WAIT_KIND_SIGNALED`.
    Signaled,
    /// `FRIDA_WAIT_KIND_STOPPED`.
    Stopped,
    /// `FRIDA_WAIT_KIND_OTHER`.
    Other,
    /// A raw value this version of the bindings has no name for.
    Unknown(i64),
}

#[cfg(not(windows))]
impl WaitKind {
    /// The variant for `raw`. Never fails: an unknown value becomes [`Self::Unknown`].
    #[must_use]
    pub fn from_raw(raw: frida_sys::FridaWaitKind) -> Self {
        match raw {
            frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_EXITED => Self::Exited,
            frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_SIGNALED => Self::Signaled,
            frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_STOPPED => Self::Stopped,
            frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_OTHER => Self::Other,
            other => Self::Unknown(i64::from(other)),
        }
    }

    /// The raw `FridaWaitKind` value.
    #[must_use]
    pub fn into_raw(self) -> frida_sys::FridaWaitKind {
        match self {
            Self::Exited => frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_EXITED,
            Self::Signaled => frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_SIGNALED,
            Self::Stopped => frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_STOPPED,
            Self::Other => frida_sys::FridaWaitKind_FRIDA_WAIT_KIND_OTHER,
            // A value from `from_raw`, so it fits, unless made by hand, when it wraps.
            Self::Unknown(raw) => raw as frida_sys::FridaWaitKind,
        }
    }

    /// frida-core's name for it, its nick, such as `local`; `unknown` for
    /// [`Self::Unknown`].
    #[must_use]
    pub fn nick(self) -> &'static str {
        match self {
            Self::Exited => "exited",
            Self::Signaled => "signaled",
            Self::Stopped => "stopped",
            Self::Other => "other",
            Self::Unknown(_) => "unknown",
        }
    }
}

#[cfg(not(windows))]
impl From<frida_sys::FridaWaitKind> for WaitKind {
    fn from(raw: frida_sys::FridaWaitKind) -> Self {
        Self::from_raw(raw)
    }
}

#[cfg(not(windows))]
impl From<WaitKind> for frida_sys::FridaWaitKind {
    fn from(value: WaitKind) -> Self {
        value.into_raw()
    }
}

#[cfg(not(windows))]
impl std::fmt::Display for WaitKind {
    /// The nick.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.nick())
    }
}

#[cfg(not(windows))]
impl std::str::FromStr for WaitKind {
    type Err = crate::gir::Error;

    /// The variant whose nick is `text`.
    fn from_str(text: &str) -> Result<Self, Self::Err> {
        match text {
            "exited" => Ok(Self::Exited),
            "signaled" => Ok(Self::Signaled),
            "stopped" => Ok(Self::Stopped),
            "other" => Ok(Self::Other),
            _ => Err(crate::gir::Error::invalid_argument(format!(
                "{text:?} is not a WaitKind"
            ))),
        }
    }
}

/// The errors that Frida operations can fail with.
///
/// The kind of a [`crate::gir::Error`]: the codes of frida-core's `frida-error-quark`
/// error domain, then those the bindings report themselves. New kinds may be added.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum ErrorKind {
    /// The frida-server is not running.
    ServerNotRunning,
    /// The specified executable was not found.
    ExecutableNotFound,
    /// The specified executable is not supported.
    ExecutableNotSupported,
    /// No process matched the request.
    ProcessNotFound,
    /// The process is not responding.
    ProcessNotResponding,
    /// An argument was invalid.
    InvalidArgument,
    /// The operation is not valid in the current state.
    InvalidOperation,
    /// Permission was denied.
    PermissionDenied,
    /// The requested address is already in use.
    AddressInUse,
    /// The operation timed out.
    TimedOut,
    /// The operation is not supported.
    NotSupported,
    /// A protocol error occurred.
    Protocol,
    /// A transport-level error occurred.
    Transport,
    /// The call was cancelled through its `Cancellable` (GIO's `G_IO_ERROR_CANCELLED`).
    Cancelled,
    /// A script's `rpc.exports` function threw, or its promise was rejected: the message is the script's, and [`Error::stack`](crate::gir::Error::stack) has its stack.
    Rpc,
    /// frida-core handed back something its declaration rules out, such as NULL where a value is promised. It is a bug in frida-core or in these bindings.
    Unexpected,
    /// An error from another GLib domain, or a code this version has no name for: [`Error::domain`](crate::gir::Error::domain) has it.
    Other,
}

impl ErrorKind {
    /// The kind of a `FridaError` code: [`Self::Other`] for one this version
    /// does not know.
    pub(crate) fn from_code(code: i32) -> Self {
        match code {
            0 => Self::ServerNotRunning,
            1 => Self::ExecutableNotFound,
            2 => Self::ExecutableNotSupported,
            3 => Self::ProcessNotFound,
            4 => Self::ProcessNotResponding,
            5 => Self::InvalidArgument,
            6 => Self::InvalidOperation,
            7 => Self::PermissionDenied,
            8 => Self::AddressInUse,
            9 => Self::TimedOut,
            10 => Self::NotSupported,
            11 => Self::Protocol,
            12 => Self::Transport,
            _ => Self::Other,
        }
    }
}

impl std::fmt::Display for ErrorKind {
    /// A description, such as `process not found`.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Self::ServerNotRunning => "the frida-server is not running",
            Self::ExecutableNotFound => "the specified executable was not found",
            Self::ExecutableNotSupported => "the specified executable is not supported",
            Self::ProcessNotFound => "no process matched the request",
            Self::ProcessNotResponding => "the process is not responding",
            Self::InvalidArgument => "an argument was invalid",
            Self::InvalidOperation => "the operation is not valid in the current state",
            Self::PermissionDenied => "permission was denied",
            Self::AddressInUse => "the requested address is already in use",
            Self::TimedOut => "the operation timed out",
            Self::NotSupported => "the operation is not supported",
            Self::Protocol => "a protocol error occurred",
            Self::Transport => "a transport-level error occurred",
            Self::Cancelled => "operation was cancelled",
            Self::Rpc => "an RPC export failed",
            Self::Unexpected => "frida-core returned what its API rules out",
            Self::Other => "another kind of error",
        })
    }
}
